#!/usr/bin/env python3
"""Export a portable, keyboard-operable local scene player; no hosted services."""
from pathlib import Path
import argparse,json,os
ROOT=Path(__file__).resolve().parents[1]
def build(destination):
 destination=Path(destination);destination.mkdir(parents=True,exist_ok=True);media=ROOT/'showcase/capri';scene=media/'scene'
 data={'config':json.loads((scene/'SCENE.json').read_text()),'masters':{name:json.loads((scene/f'{name}-master.json').read_text()) for name in ('wide','portrait')}}
 prefix=os.path.relpath(media,destination).replace(os.sep,'/')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Capri's handoff lesson · local player</title><style>:root{color-scheme:light dark}body{margin:0;background:#100a19;color:#f4f1ee;font:16px/1.5 system-ui,sans-serif}main{max-width:1200px;margin:auto;padding:16px}nav,fieldset{display:flex;flex-wrap:wrap;gap:12px;align-items:center}fieldset{border:0;padding:16px 0;margin:0}button,a,input{font:inherit}button{padding:8px 12px;background:#f4f1ee;color:#100a19;border:0;cursor:pointer}a{color:#28fb86}:focus-visible{outline:3px solid #ff1265;outline-offset:4px}canvas{display:block;width:100%;height:auto}input{min-width:120px;max-width:100%;flex:1}ol{max-width:70ch}output{min-width:8ch}p{max-width:75ch}@media(prefers-color-scheme:light){body{background:#f4f1ee;color:#100a19}a{color:#075935}button{background:#100a19;color:#f4f1ee}}</style><main><nav><a href="CAPRI_V8_PREVIEW.html">README</a><a href="CAPRI_V8_STATIC_PREVIEW.html">Complete static edition</a><a href="ENCODED.html">Actual encoded GIF</a></nav><p>Local review player. One sampled scene controls the pose, phase, dialogue and packet. No runtime execution or approval is shown.</p><fieldset aria-label="Lesson playback"><button id="play">Pause</button><button id="previous">Previous beat</button><button id="next">Next beat</button><button id="restart">Replay</button><label for="seek">Time</label><input type="range" id="seek" min="0" max="17999" step="1" value="0"><output id="clock" for="seek">0.0 / 18 s</output></fieldset><canvas id="scene" role="img" aria-label="Four-beat Capri handoff lesson. Equivalent native transcript follows."></canvas><p id="phase" role="status" aria-live="polite"></p><ol><li><b>Plan:</b> Thinker selects the request, latest corrections, relevant source, scope and checks. Originals stay retrievable.</li><li><b>Build:</b> Doer changes only the allowed source. In fixture A, blank input becomes Untitled; case, internal spaces and type constraints remain.</li><li><b>Review:</b> Reviewer compares request, correction, patch and evidence. Uncertain effects hold for reconciliation.</li><li><b>Decide:</b> Thinker reports findings, checks and limits. One write owner and ordered stages. The human decides; replay is not approval or a new task.</li></ol><p id="ready" role="status">Loading local masters…</p></main><script>
const DATA=__DATA__, PREFIX=__PREFIX__;
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),range=document.getElementById('seek'),play=document.getElementById('play'),phase=document.getElementById('phase');
const reduce=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduce.matches,time=paused?1600:0,origin=performance.now()-time,layout='',lastBeat=-1,loops=0;
const images={};function load(key,path){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[key]=im;resolve()};im.onerror=()=>reject(Error('Missing '+path));im.src=PREFIX+'/'+path;});}
function stateAt(t){return DATA.masters[layout][Math.min(1079,Math.floor(((t%18000)+18000)%18000*60/1000))];}
function paint(){const wanted=matchMedia('(max-width:760px)').matches?'portrait':'wide';if(layout!==wanted){layout=wanted;[canvas.width,canvas.height]=DATA.config.layouts[layout].size;lastBeat=-1;}const s=stateAt(time),g=DATA.config.layouts[layout],key=layout+'-'+(s.beat+1),b=DATA.config.beats[s.beat];ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(images[key+'-base'],0,0);ctx.save();ctx.globalAlpha=s.alpha;const [a,bm,c,d]=s.matrix;ctx.transform(a,c,bm,d,s.root[0],s.root[1]);ctx.translate(-s.origin[0],-s.origin[1]);ctx.drawImage(images[s.pose],0,0);ctx.restore();ctx.save();ctx.globalAlpha=s.alpha;ctx.drawImage(images[key+'-caption'],0,0);ctx.restore();ctx.drawImage(images[key+'-packet'],0,Math.round(s.packet_offset));if(s.beat===1&&s.alpha>0){const a=s.anchors.tip,b=s.leader_end;ctx.strokeStyle='#ff1265';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(...s.leader_points[0]);for(const p of s.leader_points.slice(1))ctx.lineTo(...p);ctx.stroke();ctx.fillStyle='#28fb86';ctx.beginPath();ctx.arc(...b,4,0,2*Math.PI);ctx.fill();}if(lastBeat!==s.beat){phase.textContent=b.id[0].toUpperCase()+b.id.slice(1)+' · '+b.role;lastBeat=s.beat;}range.value=Math.floor(time);document.getElementById('clock').textContent=(time/1000).toFixed(1)+' / 18 s';play.textContent=paused?'Play':'Pause';window.sceneReview={time,paused,beat:s.beat,pose:s.pose,layout,alpha:s.alpha,loops,ready:true};}
function seek(t){time=((t%18000)+18000)%18000;origin=performance.now()-time;paint();}
window.seekScene=seek;play.onclick=()=>{if(paused){origin=performance.now()-time;paused=false;}else{time=(performance.now()-origin)%18000;paused=true;}paint();};document.getElementById('restart').onclick=()=>{loops=0;paused=false;seek(0);};document.getElementById('previous').onclick=()=>{paused=true;seek(((stateAt(time).beat+3)%4)*4500+1600);};document.getElementById('next').onclick=()=>{paused=true;seek(((stateAt(time).beat+1)%4)*4500+1600);};range.oninput=()=>{paused=true;seek(Number(range.value));};reduce.addEventListener('change',e=>{if(e.matches){paused=true;seek(stateAt(time).beat*4500+1600);}});window.addEventListener('resize',()=>paint());
const tasks=['explain','point','inspect'].map(p=>load(p,'poses/'+p+'.png'));for(const l of ['wide','portrait'])for(let b=1;b<=4;b++)for(const part of ['base','caption','packet'])tasks.push(load(l+'-'+b+'-'+part,'scene/'+l+'-'+b+'-'+part+'.png'));
Promise.all(tasks).then(()=>{document.getElementById('ready').textContent='All local masters loaded. Reduced motion starts on a complete still.';origin=performance.now()-time;function tick(now){if(!paused){const elapsed=now-origin;loops=Math.floor(elapsed/18000);time=elapsed%18000;}paint();requestAnimationFrame(tick);}requestAnimationFrame(tick);}).catch(e=>{document.getElementById('ready').textContent=e.message;throw e;});
</script></html>'''
 (destination/'PLAYER.html').write_text(page.replace('__DATA__',json.dumps(data,separators=(',',':'))).replace('__PREFIX__',json.dumps(prefix)))
 encoded=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V8 actual encoded lesson</title><style>body{{background:#100a19;color:#f4f1ee;margin:0;font:16px system-ui}}main{{max-width:1200px;margin:auto}}nav{{padding:16px}}a{{color:#28fb86}}img{{width:100%;height:auto;display:block}}</style><main><nav>Actual encoded 18-second GIF · <a href="PLAYER.html">Sampled player</a> · <a href="CAPRI_V8_STATIC_PREVIEW.html">Static</a></nav><article><picture><source media="(max-width:760px)" srcset="{prefix}/scene/portrait.gif"><img src="{prefix}/scene/wide.gif" alt="Actual encoded four-beat lesson"></picture></article></main></html>'''
 (destination/'ENCODED.html').write_text(encoded)
 print('Player and encoded preview:',destination)
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('--output',required=True,type=Path);build(parser.parse_args().output)
